import numpy as np

def feature(item, bins, capacity):
    """Relative rank of a bin's residual tightness vs the population: how much tighter the worse dimension is compared to the median candidate, signed so tight bins score high."""
    cap = np.maximum(np.asarray(capacity, dtype=float), 1.0)
    b = np.asarray(bins, dtype=float) / cap[None, :]
    it = np.asarray(item, dtype=float) / cap
    rem = np.clip(b - it[None, :], 0.0, None)          # leftover per resource after placement
    tight = rem.min(axis=1)                            # tightest dimension decides feasibility
    if tight.size < 3:
        return np.zeros(tight.size)
    med = np.median(tight)
    spread = np.median(np.abs(tight - med)) + 1e-9
    return np.clip((med - tight) / spread, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Post-placement leftover on the item's lightest resource, only for skewed items (max/min demand ratio >= 1.4), else 0."""
    d = item / capacity
    k = bins.shape[0]
    ratio = np.max(d) / max(np.min(d), 1e-6)
    if ratio < 1.4:
        return np.zeros(k)
    light = int(np.argmin(d))
    return np.clip((bins[:, light] - item[light]) / capacity[light], 0.0, 1.0)
